export default function Invoices() {
  const { formatCurrency } = useCurrency();
  // const { customers } = useCustomer(); // Available for future use
  const { addIncome } = useFinancialData();
  const [invoices, setInvoices] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [editingInvoice, setEditingInvoice] = useState(null);
  const [filterStatus, setFilterStatus] = useState('all');
  const [viewingInvoice, setViewingInvoice] = useState(null);
  const [formData, setFormData] = useState({
    clientName: '',
    clientEmail: '',
    amount: '',
    dueDate: '',
    description: '',
    status: 'pending'
  });

  // Load invoices from localStorage on component mount
  useEffect(() => {
    const savedInvoices = localStorage.getItem('business-invoices');
    if (savedInvoices) {
      setInvoices(JSON.parse(savedInvoices));
    }
  }, []);

  // Save invoices to localStorage whenever invoices change
  useEffect(() => {
    localStorage.setItem('business-invoices', JSON.stringify(invoices));
    // Dispatch custom event to notify other components
    window.dispatchEvent(new CustomEvent('invoicesUpdated'));
  }, [invoices]);

  const calculateStats = () => {
    const total = invoices.reduce((sum, invoice) => sum + parseFloat(invoice.amount), 0);
    const paid = invoices.filter(invoice => invoice.status === 'paid').reduce((sum, invoice) => sum + parseFloat(invoice.amount), 0);
    const pending = invoices.filter(invoice => invoice.status === 'pending').reduce((sum, invoice) => sum + parseFloat(invoice.amount), 0);
    const overdue = invoices.filter(invoice => {
      if (invoice.status === 'paid') return false;
      const dueDate = new Date(invoice.dueDate);
      return dueDate < new Date();
    }).reduce((sum, invoice) => sum + parseFloat(invoice.amount), 0);
    
    return { total, paid, pending, overdue };
  };

  const stats = calculateStats();

  const generateInvoiceNumber = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const count = invoices.length + 1;
    return `INV-${year}${month}${day}-${String(count).padStart(3, '0')}`;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (!formData.clientName || !formData.amount || !formData.dueDate) {
      alert('Please fill in all required fields');
      return;
    }

    const invoiceData = {
      ...formData,
      id: editingInvoice ? editingInvoice.id : Date.now().toString(),
      invoiceNumber: editingInvoice ? editingInvoice.invoiceNumber : generateInvoiceNumber(),
      createdAt: editingInvoice ? editingInvoice.createdAt : new Date().toISOString(),
      amount: parseFloat(formData.amount)
    };

    if (editingInvoice) {
      setInvoices(prev => prev.map(invoice => 
        invoice.id === editingInvoice.id ? invoiceData : invoice
      ));
      } else {
      setInvoices(prev => [...prev, invoiceData]);
    }

    setFormData({
      clientName: '',
      clientEmail: '',
      amount: '',
      dueDate: '',
      description: '',
      status: 'pending'
    });
    setShowModal(false);
    setEditingInvoice(null);
  };

  const handleEdit = (invoice) => {
    setFormData({
      clientName: invoice.clientName,
      clientEmail: invoice.clientEmail || '',
      amount: invoice.amount.toString(),
      dueDate: invoice.dueDate,
      description: invoice.description || '',
      status: invoice.status
    });
    setEditingInvoice(invoice);
    setShowModal(true);
  };

  const handleDelete = (invoiceId) => {
    if (window.confirm('Are you sure you want to delete this invoice?')) {
      setInvoices(prev => prev.filter(invoice => invoice.id !== invoiceId));
    }
  };

  const handleMarkAsPaid = async (invoice) => {
    if (window.confirm(`Mark invoice ${invoice.invoiceNumber} as paid? This will add ${formatCurrency(invoice.amount)} to your income.`)) {
      // Update invoice status
      const updatedInvoices = invoices.map(inv => 
        inv.id === invoice.id ? { ...inv, status: 'paid', paidDate: new Date().toISOString() } : inv
      );
      setInvoices(updatedInvoices);

      // Add to financial income
      try {
        const result = await addIncome({
          amount: invoice.amount,
          date: new Date().toISOString().split('T')[0],
          category: 'Invoice Payment',
          source: invoice.clientName,
          notes: `Payment for invoice ${invoice.invoiceNumber}`
      });

      if (result.success) {
          alert('Invoice marked as paid and added to income successfully!');
      } else {
          alert('Invoice marked as paid, but failed to add to income: ' + result.error);
      }
    } catch (error) {
        console.error('Error adding income:', error);
        alert('Invoice marked as paid, but failed to add to income.');
      }
    }
  };

  const handlePreviewInvoice = () => {
    // Validate required fields
    if (!formData.invoiceNumber || !formData.clientName || !formData.amount || !formData.dueDate) {
      alert('Please fill in all required fields (Invoice Number, Client Name, Amount, Due Date) before previewing');
      return;
    }

    // Create a preview invoice object from current form data
    const previewInvoice = {
      id: 'preview',
      invoiceNumber: formData.invoiceNumber,
      clientName: formData.clientName,
      clientEmail: formData.clientEmail || '',
      amount: parseFloat(formData.amount),
      dueDate: formData.dueDate,
      description: formData.description || '',
      status: 'pending',
      createdAt: new Date().toISOString().split('T')[0]
    };

    setViewingInvoice(previewInvoice);
  };

  const filteredInvoices = invoices.filter(invoice => {
    if (filterStatus === 'all') return true;
    if (filterStatus === 'overdue') {
      if (invoice.status === 'paid') return false;
      const dueDate = new Date(invoice.dueDate);
      return dueDate < new Date();
    }
    return invoice.status === filterStatus;
  });

  return (
    <Container>
      <Header>
        <Title>Invoice Management</Title>
        <Button onClick={() => setShowModal(true)}>
          Create Invoice
        </Button>
      </Header>

      <StatsGrid>
        <StatCard bgColor="#f0fdf4" borderColor="#16a34a">
          <StatLabel>Total Invoices</StatLabel>
          <StatValue color="#16a34a">{formatCurrency(stats.total)}</StatValue>
        </StatCard>
        <StatCard bgColor="#f0fdf4" borderColor="#16a34a">
          <StatLabel>Paid</StatLabel>
          <StatValue color="#16a34a">{formatCurrency(stats.paid)}</StatValue>
        </StatCard>
        <StatCard bgColor="#fef3c7" borderColor="#d97706">
          <StatLabel>Pending</StatLabel>
          <StatValue color="#d97706">{formatCurrency(stats.pending)}</StatValue>
        </StatCard>
        <StatCard bgColor="#fef2f2" borderColor="#dc2626">
          <StatLabel>Overdue</StatLabel>
          <StatValue color="#dc2626">{formatCurrency(stats.overdue)}</StatValue>
        </StatCard>
      </StatsGrid>

      <FilterTabs>
        <FilterTab 
          active={filterStatus === 'all'} 
          onClick={() => setFilterStatus('all')}
        >
          All Invoices
        </FilterTab>
        <FilterTab 
          active={filterStatus === 'pending'} 
          onClick={() => setFilterStatus('pending')}
        >
          Pending
        </FilterTab>
        <FilterTab 
          active={filterStatus === 'paid'} 
          onClick={() => setFilterStatus('paid')}
        >
          Paid
        </FilterTab>
        <FilterTab 
          active={filterStatus === 'overdue'} 
          onClick={() => setFilterStatus('overdue')}
        >
          Overdue
        </FilterTab>
      </FilterTabs>

      <InvoiceGrid>
        {filteredInvoices.map(invoice => (
          <InvoiceCard key={invoice.id}>
            <InvoiceHeader>
              <InvoiceInfo>
                <InvoiceNumber>{invoice.invoiceNumber}</InvoiceNumber>
                <ClientName>{invoice.clientName}</ClientName>
                <InvoiceDate>
                  Created: {new Date(invoice.createdAt).toLocaleDateString()}
                </InvoiceDate>
              </InvoiceInfo>
              <StatusBadge status={invoice.status}>
                {invoice.status}
                {invoice.status === 'pending' && new Date(invoice.dueDate) < new Date() && ' (Overdue)'}
              </StatusBadge>
            </InvoiceHeader>
            
            <InvoiceDetails>
              <div>
                <DueDate>Due: {new Date(invoice.dueDate).toLocaleDateString()}</DueDate>
                {invoice.description && (
                  <div style={{ fontSize: '0.875rem', color: '#64748b', marginTop: '0.25rem' }}>
                    {invoice.description}
                  </div>
                )}
              </div>
              <Amount>
                <AmountValue>{formatCurrency(invoice.amount)}</AmountValue>
              </Amount>
            </InvoiceDetails>

            <Actions>
              <ActionButton onClick={() => setViewingInvoice(invoice)}>
                View
              </ActionButton>
              {invoice.status !== 'paid' && (
                <ActionButton 
                  className="primary" 
                  onClick={() => handleMarkAsPaid(invoice)}
                >
                  Mark as Paid
                </ActionButton>
              )}
              <ActionButton onClick={() => handleEdit(invoice)}>
                Edit
              </ActionButton>
              <ActionButton 
                className="danger" 
                onClick={() => handleDelete(invoice.id)}
              >
                Delete
              </ActionButton>
            </Actions>
          </InvoiceCard>
        ))}
      </InvoiceGrid>

      {showModal && (
        <Modal onClick={(e) => e.target === e.currentTarget && setShowModal(false)}>
          <ModalContent>
            <ModalHeader>
              <ModalTitle>
                {editingInvoice ? 'Edit Invoice' : 'Create New Invoice'}
              </ModalTitle>
              <CloseButton onClick={() => setShowModal(false)}>×</CloseButton>
            </ModalHeader>

            <form onSubmit={handleSubmit}>
        <FormGroup>
                <Label>Client Name *</Label>
                <Input
                  type="text"
                  value={formData.clientName}
                  onChange={(e) => setFormData(prev => ({ ...prev, clientName: e.target.value }))}
                  required
                />
        </FormGroup>

        <FormGroup>
                <Label>Client Email</Label>
          <Input
                  type="email"
                  value={formData.clientEmail}
                  onChange={(e) => setFormData(prev => ({ ...prev, clientEmail: e.target.value }))}
          />
        </FormGroup>

              <FormGroup>
                <Label>Amount *</Label>
                <Input
                type="number"
                  step="0.01"
                  min="0"
                  value={formData.amount}
                  onChange={(e) => setFormData(prev => ({ ...prev, amount: e.target.value }))}
                  required
                />
              </FormGroup>

              <FormGroup>
                <Label>Due Date *</Label>
                <Input
                  type="date"
                  value={formData.dueDate}
                  onChange={(e) => setFormData(prev => ({ ...prev, dueDate: e.target.value }))}
                  required
                />
              </FormGroup>

              <FormGroup>
                <Label>Status</Label>
                <Select
                  value={formData.status}
                  onChange={(e) => setFormData(prev => ({ ...prev, status: e.target.value }))}
                >
                  <option value="pending">Pending</option>
                  <option value="paid">Paid</option>
                </Select>
              </FormGroup>

              <FormGroup>
                <Label>Description</Label>
                <TextArea
                  value={formData.description}
                  onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                  placeholder="Describe the services or products..."
                />
              </FormGroup>

              <Actions style={{ marginTop: '1.5rem', justifyContent: 'flex-end' }}>
                <ActionButton type="button" onClick={() => setShowModal(false)}>
                  Cancel
                </ActionButton>
                <ActionButton type="button" onClick={handlePreviewInvoice} style={{ background: '#6b7280' }}>
                  Preview Invoice
                </ActionButton>
                <ActionButton type="submit" className="primary">
                  {editingInvoice ? 'Update Invoice' : 'Create Invoice'}
                </ActionButton>
              </Actions>
            </form>
          </ModalContent>
        </Modal>
      )}

      {viewingInvoice && (
        <Modal onClick={(e) => e.target === e.currentTarget && setViewingInvoice(null)}>
          <ModalContent style={{ maxWidth: '900px', width: '95%' }}>
            <ModalHeader>
              <ModalTitle>Invoice Preview</ModalTitle>
              <CloseButton onClick={() => setViewingInvoice(null)}>×</CloseButton>
            </ModalHeader>
            <InvoiceTemplate 
              invoice={viewingInvoice}
              items={[{
                description: viewingInvoice.description || 'Services rendered',
                quantity: 1,
                price: viewingInvoice.amount
              }]}
            />
          </ModalContent>
        </Modal>
      )}
    </Container>
  );
}