import React, { useState, useEffect } from 'react';
import { Routes, Route } from 'react-router-dom';
import styled from 'styled-components';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { FiMenu } from 'react-icons/fi';

// Components
import Navigation from './components/Navigation';
import Dashboard from './pages/Dashboard';
import Quotes from './pages/Quotes';
import Invoices from './pages/Invoices';
import Scanner from './pages/Scanner';
import Reports from './pages/Reports';
import Inventory from './pages/Inventory';
import Customers from './pages/Customers';
import Appointments from './pages/Appointments';
import Settings from './pages/Settings';
import Compliance from './pages/Compliance';
import DocumentTemplates from './pages/DocumentTemplates';
import FirebaseLogin from './pages/FirebaseLogin';
import Onboarding from './pages/Onboarding';
// import StorageTest from './components/StorageTest';

// Context
import { FirebaseBusinessProvider } from './context/FirebaseBusinessContext';
import { useFirebaseBusiness } from './context/FirebaseBusinessContext';
import { FinancialDataProvider } from './context/FinancialDataContext';
import { CustomerProvider } from './context/CustomerContext';
import { CurrencyProvider } from './contexts/CurrencyContext';
import { BusinessBrandingProvider } from './contexts/BusinessBrandingContext';

const AppContainer = styled.div`
  display: flex;
  min-height: 100vh;
  background-color: #f8fafc;
  
  @media (max-width: 767px) {
    flex-direction: column;
  }
`;

const MainContent = styled.main`
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  width: 100%;
  
  @media (min-width: 768px) {
    margin-left: 280px;
    width: calc(100% - 280px);
  }
`;

const TopHeader = styled.header`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem;
  background: white;
  border-bottom: 1px solid #e2e8f0;
  z-index: 10;
  
  @media (min-width: 768px) {
    display: none;
  }
`;

const HamburgerButton = styled.button`
  background: none;
  border: none;
  color: #64748b;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0.5rem;
  border-radius: 0.5rem;
  
  &:hover {
    background: #f1f5f9;
    color: #374151;
  }
`;


const MobileContent = styled.div`
  flex: 1;
  padding-bottom: 80px; /* Space for bottom navigation */
  
  @media (min-width: 768px) {
    padding-bottom: 0;
  }
`;

function AppContent() {
  const { isAuthenticated, isOnboardingComplete, loading } = useFirebaseBusiness();
  const [isLoading, setIsLoading] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    // Use Firebase loading state
    setIsLoading(loading);
  }, [loading]);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };


  if (isLoading) {
    return (
      <LoadingContainer>
        <LoadingSpinner />
        <LoadingText>Loading Business Operations App...</LoadingText>
      </LoadingContainer>
    );
  }

  if (!isAuthenticated) {
    return <FirebaseLogin />;
  }

  if (!isOnboardingComplete) {
    return <Onboarding />;
  }

  return (
    <AppContainer>
      <Navigation isMobileMenuOpen={isMobileMenuOpen} onCloseMobileMenu={() => setIsMobileMenuOpen(false)} />
      <MainContent>
        <TopHeader>
          <HamburgerButton onClick={toggleMobileMenu}>
            <FiMenu />
          </HamburgerButton>
        </TopHeader>
        <MobileContent>
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/quotes" element={<Quotes />} />
            <Route path="/invoices" element={<Invoices />} />
            <Route path="/scanner" element={<Scanner />} />
            <Route path="/reports" element={<Reports />} />
            <Route path="/inventory" element={<Inventory />} />
            <Route path="/customers" element={<Customers />} />
            <Route path="/appointments" element={<Appointments />} />
            <Route path="/compliance" element={<Compliance />} />
            <Route path="/settings" element={<Settings />} />
            <Route path="/templates" element={<DocumentTemplates />} />
            {/* <Route path="/storage-test" element={<StorageTest />} /> */}
          </Routes>
        </MobileContent>
      </MainContent>
      <ToastContainer
        position="top-right"
        autoClose={3000}
        hideProgressBar={false}
        newestOnTop={false}
        closeOnClick
        rtl={false}
        pauseOnFocusLoss
        draggable
        pauseOnHover
      />
    </AppContainer>
  );
}

const LoadingContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
  background-color: #f8fafc;
`;

const LoadingSpinner = styled.div`
  width: 50px;
  height: 50px;
  border: 4px solid #e2e8f0;
  border-top: 4px solid #3b82f6;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin-bottom: 20px;

  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
`;

const LoadingText = styled.p`
  color: #64748b;
  font-size: 16px;
  font-weight: 500;
`;

function App() {
  return (
    <FirebaseBusinessProvider>
      <FinancialDataProvider>
        <CustomerProvider>
          <CurrencyProvider>
            <BusinessBrandingProvider>
              <AppContent />
            </BusinessBrandingProvider>
          </CurrencyProvider>
        </CustomerProvider>
      </FinancialDataProvider>
    </FirebaseBusinessProvider>
  );
}

export default App;
