import React, { createContext, useContext, useState, useEffect } from 'react';

const BusinessBrandingContext = createContext();

export const useBusinessBranding = () => {
  const context = useContext(BusinessBrandingContext);
  if (!context) {
    throw new Error('useBusinessBranding must be used within a BusinessBrandingProvider');
  }
  return context;
};

export const BusinessBrandingProvider = ({ children }) => {
  const [businessInfo, setBusinessInfo] = useState({
    logo: '',
    businessName: '',
    businessAddress: '',
    businessPhone: '',
    businessEmail: '',
    businessWebsite: '',
    bankDetails: {
      bankName: '',
      accountNumber: '',
      routingNumber: '',
      swiftCode: '',
      accountHolderName: '',
      iban: ''
    },
    taxInfo: {
      taxId: '',
      vatNumber: '',
      businessRegistration: ''
    }
  });

  // Load business info from localStorage on component mount
  useEffect(() => {
    const savedBusinessInfo = localStorage.getItem('business-branding-info');
    if (savedBusinessInfo) {
      setBusinessInfo(JSON.parse(savedBusinessInfo));
    }
  }, []);

  // Save business info to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('business-branding-info', JSON.stringify(businessInfo));
  }, [businessInfo]);

  const updateBusinessInfo = (updates) => {
    setBusinessInfo(prev => ({
      ...prev,
      ...updates
    }));
  };

  const updateBankDetails = (bankUpdates) => {
    setBusinessInfo(prev => ({
      ...prev,
      bankDetails: {
        ...prev.bankDetails,
        ...bankUpdates
      }
    }));
  };

  const updateTaxInfo = (taxUpdates) => {
    setBusinessInfo(prev => ({
      ...prev,
      taxInfo: {
        ...prev.taxInfo,
        ...taxUpdates
      }
    }));
  };

  const uploadLogo = (logoData) => {
    setBusinessInfo(prev => ({
      ...prev,
      logo: logoData
    }));
  };

  const value = {
    businessInfo,
    updateBusinessInfo,
    updateBankDetails,
    updateTaxInfo,
    uploadLogo
  };

  return (
    <BusinessBrandingContext.Provider value={value}>
      {children}
    </BusinessBrandingContext.Provider>
  );
};
