import React from 'react';
import styled from 'styled-components';
import { 
  FiArrowLeft,
  FiCamera,
  // FiPlus
} from 'react-icons/fi';

const ScannerContainer = styled.div`
  padding: 1rem;
  max-width: 400px;
  margin: 0 auto;
  background: #f8fafc;
  min-height: 100vh;
`;

const TopBar = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3rem;
  padding: 0 0.5rem;
`;

const BackButton = styled.button`
  background: none;
  border: none;
  color: #1e293b;
  font-size: 1.25rem;
  cursor: pointer;
  padding: 0.5rem;
  border-radius: 6px;
  
  &:hover {
    background: #f1f5f9;
  }
`;

const Title = styled.h1`
  font-size: 1.5rem;
  font-weight: 700;
  color: #1e293b;
  margin: 0;
`;

const MainContent = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 2rem 1rem;
`;

const IconContainer = styled.div`
  width: 120px;
  height: 120px;
  background: #f0fdfa;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 2rem;
`;

const DocumentIcon = styled.div`
  width: 60px;
  height: 60px;
  background: #14b8a6;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  
  &::before {
    content: '';
    position: absolute;
    top: 8px;
    left: 8px;
    right: 8px;
    height: 2px;
    background: white;
    border-radius: 1px;
  }
  
  &::after {
    content: '';
    position: absolute;
    top: 12px;
    left: 8px;
    right: 8px;
    height: 1px;
    background: white;
    border-radius: 1px;
  }
`;

const CornerBrackets = styled.div`
  position: absolute;
  width: 100%;
  height: 100%;
  
  &::before {
    content: '';
    position: absolute;
    top: 4px;
    left: 4px;
    width: 8px;
    height: 8px;
    border-top: 2px solid white;
    border-left: 2px solid white;
  }
  
  &::after {
    content: '';
    position: absolute;
    top: 4px;
    right: 4px;
    width: 8px;
    height: 8px;
    border-top: 2px solid white;
    border-right: 2px solid white;
  }
`;

const MainText = styled.h2`
  font-size: 1.25rem;
  font-weight: 600;
  color: #1e293b;
  margin: 0 0 0.75rem 0;
  line-height: 1.4;
`;

const SubText = styled.p`
  font-size: 1rem;
  color: #6b7280;
  margin: 0 0 3rem 0;
  line-height: 1.5;
`;

const ScanButton = styled.button`
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 2rem;
  background: #14b8a6;
  color: white;
  border: none;
  border-radius: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 4px 12px rgba(20, 184, 166, 0.3);
  
  &:hover {
    background: #0d9488;
    transform: translateY(-1px);
    box-shadow: 0 6px 16px rgba(20, 184, 166, 0.4);
  }
  
  &:active {
    transform: translateY(0);
  }
`;

const CameraIcon = styled.div`
  font-size: 1.25rem;
`;

export default function Scanner() {
  const handleScanClick = () => {
    // Handle scan/upload functionality
    console.log('Scan or Upload clicked');
  };

  return (
    <ScannerContainer>
      <TopBar>
        <BackButton>
          <FiArrowLeft />
        </BackButton>
        <Title>Scan or Upload</Title>
        <div></div>
      </TopBar>

      <MainContent>
        <IconContainer>
          <DocumentIcon>
            <CornerBrackets />
          </DocumentIcon>
        </IconContainer>

        <MainText>
          Capture or upload documents to automatically create expense transactions.
        </MainText>

        <SubText>
          Our OCR technology will extract the vendor, date, and amount for you.
        </SubText>

        <ScanButton onClick={handleScanClick}>
          <CameraIcon>
            <FiCamera />
          </CameraIcon>
          Scan or Upload
        </ScanButton>
      </MainContent>
    </ScannerContainer>
  );
}